"""Regression coverage for the behavior defined in SPEC.md."""

import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [{"converted": True}, {"converted": None}, {"converted": False}]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty_returns_float_zero():
    result = conversion_rate([])
    assert result == 0.0
    assert isinstance(result, float)


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    result = pooled_conversion_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4, 8], 2, 12), ([1, 2, 4], 1, 4), ([1, 2], 0, 0),
     ([1, 2], 2, 3), ([1, 2], 10, 3), ([], 3, 0), ([], 0, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_flags_and_field_whitespace():
    assert parse_session_log([" a , 2 , 1 \n", " b , -1 , 0 ", " c , 0 , \t"]) == [
        session("a", 2, True), session("b", -1, False), session("c", 0, None),
    ]


def test_parse_session_log_skips_blank_whitespace_and_comments():
    lines = ["", " \t\n", "# comment", " \t# not,a,session", "x,3,1"]
    assert parse_session_log(iter(lines)) == [session("x", 3, True)]
    assert parse_session_log(lines[:-1]) == []


@pytest.mark.parametrize("bad_line", ["x,2", "x,2,1,extra", "x,no,1", "x,1.5,0", "x,,1"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(["# comment", "", " \t", "ok,1,1", bad_line])


def test_dedupe_sessions_last_duplicate_id_wins_and_result_is_sorted():
    # The last occurrence wins even when its day is earlier than the old record's.
    old_a = session("a", 9, True)
    old_b = session("b", 1, True)
    new_a = session("a", 2, False)
    new_b = session("b", 2, None)
    first = session("z", 0, True)
    events = [old_a, old_b, new_b, first, new_a]
    assert dedupe_sessions(events) == [first, new_a, new_b]
    assert events == [old_a, old_b, new_b, first, new_a]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_and_gaps():
    events = [
        session("outside-before", 0, True), session("start", 1, True),
        session("false", 2, False), session("unknown", 2, None),
        session("end-a", 4, True), session("end-b", 4, True),
        session("outside-after", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [1, 0, 0, 2]
    assert daily_conversion_counts(events, 4, 4) == [2]
    assert daily_conversion_counts(events, 4, 1) == []


def test_daily_conversion_counts_no_sessions():
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]
    assert daily_conversion_counts([], 2, 1) == []


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_campaign_summary_pooled_rate_calendar_window_and_nonempty_groups(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 4, True), session("c", 5, None)],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_ranking_ties_and_empty_groups():
    groups = {
        "z": [{"converted": True}, {"converted": False}],
        "empty": [],
        "best": [{"converted": True}],
        "a": [{"converted": True}, {"converted": None}],
        "zero": [{"converted": False}],
    }
    assert top_converting_groups(groups, 3) == ["best", "a", "z"]
    assert top_converting_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({"empty": []}, 2) == []
    assert top_converting_groups({}, 2) == []


def test_conversion_rate_by_group_sorted_keys_and_empty_group():
    groups = {
        "z": [{"converted": True}, {"converted": None}],
        "b": [],
        "a": [{"converted": False}],
    }
    result = conversion_rate_by_group(groups)
    assert result == {"a": 0.0, "b": None, "z": 0.5}
    assert list(result) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 2, 3, 0, 4], 2),
     ([1, 2, -1, 3, 4, 5], 3), ([1, 2, 3, 0, 4], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
